#include <stdio.h>
#include <string.h>
int main() {
    char s[100005]; if (scanf("%s", s) != 1) return 0;
    char stack[100005]; int top = 0;
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') stack[top++] = c;
        else {
            if (top == 0) { puts("false"); return 0; }
            char o = stack[--top];
            if (c == ')' && o != '(') { puts("false"); return 0; }
            if (c == ']' && o != '[') { puts("false"); return 0; }
            if (c == '}' && o != '{') { puts("false"); return 0; }
        }
    }
    puts(top == 0 ? "true" : "false");
    return 0;
}

