#include <iostream>
#include <string>
#include <stack>
using namespace std;
int main() {
    string s; if (cin >> s) {
        stack<char> st;
        bool ok = true;
        for (char c : s) {
            if (c == '(' || c == '[' || c == '{') st.push(c);
            else {
                if (st.empty()) { ok = false; break; }
                char o = st.top(); st.pop();
                if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) { ok = false; break; }
            }
        }
        cout << (ok && st.empty() ? "true" : "false") << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.Stack;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            Stack<Character> st = new Stack<>();
            boolean ok = true;
            for (char c : s.toCharArray()) {
                if (c == '(' || c == '[' || c == '{') st.push(c);
                else {
                    if (st.isEmpty()) { ok = false; break; }
                    char o = st.pop();
                    if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) { ok = false; break; }
                }
            }
            System.out.println(ok && st.isEmpty() ? "true" : "false");
        }
    }
}

