const fs = require("fs");
function main() {
    const s = fs.readFileSync(0, "utf-8").trim();
    const stack = [];
    const matching = { ")": "(", "}": "{", "]": "[" };
    for (const c of s) {
        if (c === "(" || c === "{" || c === "[") stack.push(c);
        else if (matching[c]) {
            if (stack.length === 0 || stack[stack.length - 1] !== matching[c]) {
                console.log("false"); return;
            }
            stack.pop();
        }
    }
    console.log(stack.length === 0 ? "true" : "false");
}
main();

